source('code/00_config.R');suppressPackageStartupMessages(library(openxlsx))
qa<-rd(path('audit/FINAL_QA_checks.tsv'));stopifnot(nrow(qa)>0,all(qa$status=='PASS'))
reg<-readRDS(path('audit/figure_registry.rds'));ids<-names(reg$captions)
release<-path('FINAL_SUBMISSION_PACKAGE');dir.create(release,showWarnings=FALSE)
copy_file<-function(src,dest){stopifnot(file.exists(src));dir.create(dirname(dest),recursive=TRUE,showWarnings=FALSE);stopifnot(file.copy(src,dest,overwrite=TRUE))}
copy_tree<-function(src,dest,exclude=character()){fs<-list.files(src,recursive=TRUE,full.names=TRUE,all.files=TRUE,no..=TRUE);fs<-fs[!file.info(fs)$isdir];for(f in fs){rel<-substring(f,nchar(src)+2);if(length(exclude)&&any(vapply(exclude,function(e)grepl(e,rel),logical(1))))next;copy_file(f,file.path(dest,rel))}}
for(sub in c('Manuscript','Main_figures','Supplementary_figures','Single_panels','Tables','Figure_source_Excel','Clinical_and_data_tables','Raw_SSB_matrices','R_code','Audit'))dir.create(file.path(release,sub),showWarnings=FALSE)
