copy_tree(path('figures/main'),file.path(release,'Main_figures'))
for(n in names(reg$supplementary_layout))for(ext in c('.pdf','.svg','.tiff','.png'))copy_file(path('figures/supplementary',paste0('Figure_',n,ext)),file.path(release,'Supplementary_figures',paste0('Figure_',n,ext)))
for(id in ids){for(ext in c('.pdf','.svg','.tiff','.png'))copy_file(path('figures/panels',paste0(id,ext)),file.path(release,'Single_panels',paste0(id,ext)));copy_file(path('excel/panels',paste0(id,'_source_data.xlsx')),file.path(release,'Figure_source_Excel/panels',paste0(id,'_source_data.xlsx')));for(f in c('legend_EN_ZH.md','results_and_legend_EN_ZH.md'))copy_file(path('source_data',id,f),file.path(release,'Single_panels/Legends_and_results',id,f))}
for(n in c(names(reg$main),paste0('Figure_',names(reg$supplementary_layout))))copy_file(path('excel/figures',paste0(n,'_source_data.xlsx')),file.path(release,'Figure_source_Excel/figures',paste0(n,'_source_data.xlsx')))
