copy_tree(path('excel/master_tables'),file.path(release,'Clinical_and_data_tables'))
copy_tree(path('excel/raw_matrices'),file.path(release,'Raw_SSB_matrices'))
scripts<-list.files(path('code'),pattern='[.]R$',full.names=TRUE);scripts<-scripts[!basename(scripts)%in%c('00_prepare.R','98_build_figures_QC261.R')];for(f in scripts)copy_file(f,file.path(release,'R_code',basename(f)))
