for(f in c('FINAL_QA_checks.tsv','FINAL_QA_report.xlsx','package_version_lock.tsv','R_sessionInfo.txt','metric_validation.tsv','numerical_change_log.tsv','PDF_font_audit.tsv','Excel_panel_roundtrip.tsv','Excel_raw_matrix_roundtrip.tsv'))copy_file(path('audit',f),file.path(release,'Audit',f))

