writeLines(c('# CONTROLLED DATA — DO NOT UPLOAD TO PUBLIC GITHUB','Contains pseudonymized individual clinical information and genomic matrices, plus restricted original clinical files. This is local preparation, not permission for disclosure.','The --mode=processed pipeline reproduces statistics/models/plots from the supplied matrices. Cached model-complete files correspond to the fixed inputs; use a new output version for any changed data. Full de novo reruns can remove ONLY the named model cache files in a copied working directory, not the input archive.','The --mode=full rerun additionally requires the original BED and reference paths, not distributed publicly.','Use --mode=figures to regenerate independent panels, all four main composites, supplementary composites, source Excel files and manuscript from validated results.','Publication documents require authors to complete the listed ethics/experimental/repository fields.'),file.path(ctl,'README_CONTROLLED.md'))

# Exact package index and checksum inventory, including editable figures.
index<-data.table(panel=ids,pdf=paste0('Single_panels/',ids,'.pdf'),source_excel=paste0('Figure_source_Excel/panels/',ids,'_source_data.xlsx'),R_script=paste0('R_code/panels/',ids,'.R'));savebook(list(Panels=index,Main_membership=rbindlist(lapply(names(reg$main),function(n)data.table(figure=n,panel=reg$main[[n]]))),Supplementary_membership=rbindlist(lapply(names(reg$supplementary_layout),function(n)data.table(figure=n,panel=reg$supplementary_layout[[n]])))),file.path(release,'DELIVERY_INDEX.xlsx'))
notes<-c('SSB FINAL SUBMISSION MATERIALS — independent QC261 / EXON-primary version','Final groups: HC144; AD89=author-reviewed Core 1-positive AD pathology; Other28=Core 1-negative cognitive disorders. Final cohort261, adjusted models259, direct pathology117.','Figure1 uses three groups throughout. P values are nominal numerical labels; full BH/FDR results remain in statistics.','Metrics: SSB_LPKM=nonredundant within-gene count*1e10/complete-library D. No length division or TPM. Ri uses the same unfiltered mean GENE total for every region and subgroup: B=875180.6475095785.','Contents: editable single-panel and composite PDF/SVG; separate600dpiTIFF; full R code; panel and composite source Excel; Word Table1; one necessary supplementary workbook; English/Chinese manuscript and legends; final grouping/clinical/data/statistics Excel; four full raw count/LPKM/log matrices.','EXON primary findings360 (11 higher349 lower); GENE sensitivity3013. Source EXON internal AUC0.885759. All direct AD–Other regional feature contrasts had zero BH-threshold discoveries. These are atlas/disease-source associations, not proven AD-specific biomarkers.','No original directly identifying clinical workbook is included in this submission folder. Original clinical files are in the independent project INTERNAL_RESTRICTED archive. Coded individual source data still require authorized access and consent review before public posting.','Manual GitHub preparation is outside this folder: ../GITHUB_READY/PUBLIC_CODE_AND_AGGREGATE and ../GITHUB_READY/CONTROLLED_REPRODUCTION_DO_NOT_UPLOAD. Nothing has been uploaded.','Open DELIVERY_INDEX.xlsx for panel-to-PDF/Excel/R mapping. Main manuscript: Manuscript/Manuscript_EN.docx. Detailed formulas: Manuscript/Detailed_methods_and_formulas.docx. Grouping: Clinical_and_data_tables/Final_analysis_grouping.xlsx. Clinical: Clinical_and_data_tables/Clinical_final_observed.xlsx.','Before submission, authors must complete ethics/consent, recruitment/experimental details, biomarker-platform thresholds, author/funding/conflict declarations and approved repository/access information. No journal has been selected; Nature-family generic preparation is used.');writeLines(notes,file.path(release,'README.txt'));writeLines(c(paste0('# ',basename(ROOT)),'Complete analysis outputs are in FINAL_SUBMISSION_PACKAGE/README.txt.','The GitHub preparation folder is GITHUB_READY; controlled original clinical files are INTERNAL_RESTRICTED.','For the current reviewed cohort use excel/master_tables/Final_analysis_grouping.xlsx and Clinical_final_observed.xlsx.','Run Rscript code/99_run_all.R with an explicit mode. All stages write logs and halt on failed checks.'),path('README.md'))
fs<-list.files(release,recursive=TRUE,full.names=TRUE);fs<-fs[!file.info(fs)$isdir];manifest<-data.table(file=substring(fs,nchar(release)+2),bytes=file.info(fs)$size,md5=unname(tools::md5sum(fs)));wr(manifest,file.path(release,'FILE_CHECKSUMS.tsv'))
pubfs<-list.files(pub,recursive=TRUE,full.names=TRUE);bad<-grepl('[.](xlsx|rds|bed|bam|fastq)$|original_clinical|participant_mean_OOF|all_OOF',pubfs);stopifnot(!any(bad));wr(data.table(check='Public-folder individual raw inputs absent',status='PASS',files=length(pubfs)),path('audit/GitHub_public_privacy_check.tsv'))
logstage('package',paste('PASS independent submission folder:',nrow(manifest),'files;',length(ids),'panels; controlled data separated; no external upload'))
